        listRepositoryFiles: vi.fn(async () => []),
        listTopLevelFolders: vi.fn(async () => []),
        loadActionFiles: vi.fn(async () => []),
        loadProject: vi.fn(async () => ({ files: [], workingFolder: 'design' })),
        loadProjectRoot: vi.fn(async () => ({ files: [], workingFolder: 'design' })),
        loadProjectConfig: vi.fn(async () => null),
        moveFiles: vi.fn(),
        push: vi.fn(),
        saveProjectConfig: vi.fn(),
    }
}

function renderProjectSurface(isGithubAuthenticated = false) {
    function ProjectSurface() {
        return (
            <>
                <DialogDisplay />
                <ProjectToolbarMenu accessToken="token" isGithubAuthenticated={isGithubAuthenticated} />
                <ProjectWorkspace
                    auth={auth}
                    isMenuOpen={false}
                    onLeftPanelInteraction={vi.fn()}
                />
            </>
        )
    }

    return render(
        <AppThemeProvider>
            <ProjectSurface />
        </AppThemeProvider>,
    )
}

function openTreeBranches(treeElement: HTMLElement, branchNames: string[]) {
    const tree = within(treeElement)
    for (const branchName of branchNames) {
        const branchButton = tree.queryByRole('button', { name: new RegExp(`^${branchName} \\d+$`, 'u') })
        const treeItem = branchButton?.closest('[role="treeitem"]')
        if (branchButton && treeItem?.getAttribute('aria-expanded') === 'false') fireEvent.click(branchButton)
    }
}

async function openProjectDialog() {
    fireEvent.click(screen.getByRole('button', { name: 'Project' }))
    fireEvent.click(screen.getByRole('menuitem', { name: 'Open project...' }))
    await screen.findByRole('heading', { name: 'Open project' })
}

async function chooseBranch(branch: string) {
    fireEvent.mouseDown(screen.getByRole('combobox', { name: 'Branch' }))
    fireEvent.click(await screen.findByRole('option', { name: branch }))
}

async function requestLocalProject() {
    fireEvent.click(screen.getByRole('button', { name: 'Project' }))
    fireEvent.click(screen.getByRole('menuitem', { name: 'Open project...' }))
    fireEvent.mouseDown(await screen.findByRole('combobox', { name: 'Source' }))
    fireEvent.click(await screen.findByRole('option', { name: 'Local folder' }))
    fireEvent.click(screen.getByRole('button', { name: 'Choose local repository folder' }))
}

import { act, cleanup, render, screen, within } from '@testing-library/react'
import { createRef } from 'react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { UseGithubAuthResult } from '../../auth/use_github_auth'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { AppThemeProvider } from '../../theme/theme_provider'
import { MobileMainWindow } from './mobile_main_window'

const auth: UseGithubAuthResult = {
    accessToken: null,
    errorMessage: null,
    isAuthenticated: false,
    isLoadingUser: false,
    logout: vi.fn(),
    savePersonalAccessToken: vi.fn(),
    status: 'idle',
    user: null,
}

function renderMobileMainWindow(showNavigationInCards: boolean) {
    const rightPanelContainerRef = createRef<HTMLDivElement>()

    return render(
        <AppThemeProvider>
            <MobileMainWindow
                auth={auth}
                cardNavigation={<nav>Board navigation</nav>}
                isMenuOpen
                leftPanel={<nav>Project navigation</nav>}
                onCloseMenu={vi.fn()}
                rightPanel={<main>Project workspace</main>}
                rightPanelContainerRef={rightPanelContainerRef}
                showNavigationInCards={showNavigationInCards}
            />
        </AppThemeProvider>,
    )
}

describe('MobileMainWindow', () => {
    afterEach(() => {
        cleanup()
        workspaceViewService.setViewMode('cards')
    })

    it('shows navigation in the drawer when requested', () => {
        renderMobileMainWindow(true)

        expect(screen.getByText('Project navigation')).toBeInTheDocument()
        expect(screen.getByText('Project workspace')).toBeInTheDocument()
        expect(screen.getByRole('button', { name: /Switch to (dark|light) theme/ })).toBeInTheDocument()
        expect(screen.getByRole('button', { name: 'GitHub account' })).toBeInTheDocument()
    })

    it('pins project status directly above the account footer', () => {
        renderMobileMainWindow(true)

        const status = screen.getByRole('region', { name: 'Project status' })
        const footer = screen.getByRole('contentinfo')
        const separator = status.nextElementSibling

        expect(within(status).getByText('Cards')).toBeInTheDocument()
        expect(within(status).getByText('Local save')).toBeInTheDocument()
        expect(within(status).getByText('Remote push')).toBeInTheDocument()
        expect(within(status).getByRole('button', { name: 'Running agents: 0' })).toBeInTheDocument()
        expect(within(status).getByRole('button', { name: 'Agent token usage summary' })).toBeInTheDocument()
        expect(within(status).queryByText('Remote control')).toBeNull()
        expect(within(status).queryByText('Caps Lock')).toBeNull()
        expect(separator?.tagName).toBe('HR')
        expect(separator?.nextElementSibling).toBe(footer)
        expect(screen.getByTestId('mobile-navigation-scroll-region')).toHaveStyle({ overflow: 'auto' })
    })

    it('hides navigation without hiding workspace content', () => {
        renderMobileMainWindow(false)

        expect(screen.getByText('Project navigation')).not.toBeVisible()
        expect(screen.getByText('Board navigation')).toBeVisible()
        expect(screen.getByText('Project workspace')).toBeInTheDocument()
    })

    it('contains board navigation in its own vertical scroll region', () => {
        renderMobileMainWindow(false)

        const navigationRegion = screen.getByTestId('mobile-navigation-region')
        const cardScrollRegion = screen.getByTestId('mobile-card-navigation-scroll-region')

        expect(navigationRegion).toHaveStyle({ overflow: 'hidden' })
        expect(cardScrollRegion).toHaveStyle({ height: '100%', overflowX: 'hidden', overflowY: 'auto' })
        expect(cardScrollRegion).toContainElement(screen.getByText('Board navigation'))
        expect(cardScrollRegion).toBeVisible()
        expect(screen.getByTestId('mobile-navigation-scroll-region')).not.toBeVisible()
    })

    it('shows navigation in text view without rerendering it', () => {
        renderMobileMainWindow(false)
        const navigation = screen.getByText('Project navigation')

        act(() => workspaceViewService.setViewMode('text'))

        const navigationScrollRegion = screen.getByTestId('mobile-navigation-scroll-region')

        expect(screen.getByText('Project navigation')).toBe(navigation)
        expect(navigation).toBeVisible()
        expect(navigationScrollRegion).toHaveStyle({ overflow: 'auto' })
        expect(navigationScrollRegion).toContainElement(navigation)
        expect(screen.getByText('Board navigation')).not.toBeVisible()
    })
})

import { describe, expect, it } from 'vitest'
import type { ProjectReference } from '../../data/data_types'
import { CARD_PATH_CHANGED_EVENT, type CardPathChangedEventDetail, type DataService, type DataServiceState } from '../data/data_service'
import { WorkspaceViewService } from './workspace_view_service'

class TestDataService extends EventTarget {
    private project: ProjectReference | null = null

    getState(): DataServiceState {
        return { project: this.project, runningAgents: [], snapshot: null }
    }

    setProject(project: ProjectReference | null) {
        this.project = project
        this.dispatchEvent(new Event('changed'))
    }

    publishSnapshotChange() {
        this.dispatchEvent(new Event('changed'))
    }

    publishCardPathChange(fromPath: string, toPath: string) {
        const detail: CardPathChangedEventDetail = { fromPath, toPath }
        this.dispatchEvent(new CustomEvent<CardPathChangedEventDetail>(CARD_PATH_CHANGED_EVENT, { detail }))
    }
}

describe('WorkspaceViewService', () => {
    it('keeps view state for project data changes and resets it when project identity changes', () => {
        const dataService = new TestDataService()
        dataService.setProject({ branch: 'main', id: 'project' })
        const service = new WorkspaceViewService(dataService as unknown as DataService)
        service.setViewMode('text')
        service.selectPath('design/F-1.md')

        dataService.publishSnapshotChange()
        expect(service.getSnapshot()).toEqual({ selectedPath: 'design/F-1.md', viewMode: 'text' })

        dataService.setProject({ branch: 'feature', id: 'project' })
        expect(service.getSnapshot()).toEqual({ selectedPath: null, viewMode: 'cards' })
    })

    it('follows the selected card when its file is renamed', () => {
        const dataService = new TestDataService()
        dataService.setProject({ branch: 'main', id: 'project' })
        const service = new WorkspaceViewService(dataService as unknown as DataService)
        service.selectPath('design/F-1-root.md')

        dataService.publishCardPathChange('design/F-2-other.md', 'design/F-2-renamed.md')
        expect(service.getSnapshot().selectedPath).toBe('design/F-1-root.md')

        dataService.publishCardPathChange('design/F-1-root.md', 'design/F-1-renamed.md')
        expect(service.getSnapshot().selectedPath).toBe('design/F-1-renamed.md')
    })
})

const services = new Map<string, unknown>()

export function register<TService>(name: string, service: TService): TService {
    services.set(name, service)

    return service
}

export function getService<TService>(name: string): TService {
    const service = services.get(name)
    if (!service) throw new Error(`Service is not registered: ${name}`)

    return service as TService
}
